"use server";

import { revalidatePath } from "next/cache";

// Simulated in-memory store for the user's notification preference.
// In a real app, this would be a database call.
let notificationsEnabled = false;

export async function getNotificationPreference(): Promise<boolean> {
  return notificationsEnabled;
}

export async function toggleNotificationPreference(): Promise<void> {
  notificationsEnabled = !notificationsEnabled;

  // Refresh the current page so the UI reflects the updated preference
  // without redirecting to a different route.
  revalidatePath("/");
}

